// Local reference walking routes follow mapped OSM roads, never a straight line through buildings.
const rad=d=>d*Math.PI/180;
const pair=p=>Array.isArray(p)?p:[p.lng,p.lat];
export function distance(a,b){a=pair(a);b=pair(b);const dlat=rad(b[1]-a[1]),dlng=rad(b[0]-a[0]);return 6371000*2*Math.asin(Math.min(1,Math.sqrt(Math.sin(dlat/2)**2+Math.cos(rad(a[1]))*Math.cos(rad(b[1]))*Math.sin(dlng/2)**2)));}
export function direction(a,b){a=pair(a);b=pair(b);const y=Math.sin(rad(b[0]-a[0]))*Math.cos(rad(b[1])),x=Math.cos(rad(a[1]))*Math.sin(rad(b[1]))-Math.sin(rad(a[1]))*Math.cos(rad(b[1]))*Math.cos(rad(b[0]-a[0]));const bearing=(Math.atan2(y,x)*180/Math.PI+360)%360;return {bearing,name:['北','东北','东','东南','南','西南','西','西北'][Math.round(bearing/45)%8]};}
export const meters=n=>n>=1000?(n/1000).toFixed(1)+' 公里':Math.round(n)+' 米';
export function navigationURL(target,origin,{native=true}={}){const url=new URL('https://uri.amap.com/navigation');const params={to:`${target.lng.toFixed(6)},${target.lat.toFixed(6)},${target.name}`,mode:'walk',coordinate:'wgs84',src:'explore-shoot',callnative:native?'1':'0'};if(origin)params.from=`${origin.lng.toFixed(6)},${origin.lat.toFixed(6)},${origin.name||'当前位置'}`;url.search=new URLSearchParams(params);return url.href;}
// Official AMap mobile URI: dev=1 converts GPS coordinates; t=2 means walking.
export function nativeNavigationURL(target,origin,platform){if(!['ios','android'].includes(platform))return null;const params={sourceApplication:'探索与拍摄',dlat:target.lat.toFixed(6),dlon:target.lng.toFixed(6),dname:target.name,dev:'1',t:'2',m:'0'};if(origin)Object.assign(params,{slat:origin.lat.toFixed(6),slon:origin.lng.toFixed(6),sname:origin.name||'当前位置'});return (platform==='ios'?'iosamap://path?':'amapuri://route/plan/?')+new URLSearchParams(params);}
export function roadGraph(geo){const nodes=new Map(),edges=[];const get=(c,nodeId)=>{const key=nodeId?'osm:'+nodeId:c.map(x=>x.toFixed(7)).join(',');if(!nodes.has(key))nodes.set(key,{key,c,links:[]});return nodes.get(key);};for(const f of geo.features||[]){const p=f.properties||{};if(f.geometry?.type!=='LineString'||!['residential','footway','path','pedestrian','service','living_street','track','steps','unclassified','tertiary','secondary'].includes(p.kind)||p.foot==='no'||(['private','no'].includes(p.access)&&!['yes','designated','permissive'].includes(p.foot)))continue;const cs=f.geometry.coordinates;for(let i=1;i<cs.length;i++){if(p.barriers?.[i-1]||p.barriers?.[i])continue;const a=get(cs[i-1],p.nodeIds?.[i-1]),b=get(cs[i],p.nodeIds?.[i]),length=distance(a.c,b.c);if(!length)continue;const forward=p.footOneway!=='-1',reverse=p.footOneway!=='yes';if(forward)a.links.push({to:b.key,length});if(reverse)b.links.push({to:a.key,length});edges.push({a,b,length,forward,reverse});}}return {nodes,edges};}
function snap(p,graph){p=pair(p);const scale=Math.cos(rad(p[1]));let best;for(const edge of graph.edges){const a=edge.a.c,b=edge.b.c,x=(b[0]-a[0])*scale,y=b[1]-a[1],t=Math.max(0,Math.min(1,((p[0]-a[0])*scale*x+(p[1]-a[1])*y)/(x*x+y*y)));const c=[a[0]+t*(b[0]-a[0]),a[1]+t*(b[1]-a[1])],gap=distance(p,c);if(!best||gap<best.gap)best={edge,c,t,gap};}return best;}
export function walkingLeg(graph,start,end){const a=snap(start,graph),b=snap(end,graph);if(!a||!b||a.gap>250||b.gap>250)return {available:false,reason:'点位附近缺少可用道路资料'};const costs=new Map(),prev=new Map(),pending=new Set(graph.nodes.keys());const starts=[];if(a.edge.reverse||a.t===0)starts.push([a.edge.a.key,a.edge.length*a.t]);if(a.edge.forward||a.t===1)starts.push([a.edge.b.key,a.edge.length*(1-a.t)]);for(const [key,len] of starts)costs.set(key,len);while(pending.size){let current,min=Infinity;for(const key of pending){const cost=costs.get(key)??Infinity;if(cost<min){current=key;min=cost;}}if(!current)break;pending.delete(current);for(const link of graph.nodes.get(current).links){if(!pending.has(link.to))continue;const next=min+link.length;if(next<(costs.get(link.to)??Infinity)){costs.set(link.to,next);prev.set(link.to,current);}}}let target,length=Infinity;const ends=[];if(b.edge.forward||b.t===0)ends.push([b.edge.a.key,b.edge.length*b.t]);if(b.edge.reverse||b.t===1)ends.push([b.edge.b.key,b.edge.length*(1-b.t)]);for(const [key,extra] of ends){const total=(costs.get(key)??Infinity)+extra;if(total<length){length=total;target=key;}}let path;if(a.edge===b.edge&&((b.t>=a.t&&a.edge.forward)||(b.t<=a.t&&a.edge.reverse))&&a.edge.length*Math.abs(a.t-b.t)<=length){length=a.edge.length*Math.abs(a.t-b.t);path=[a.c,b.c];}else if(target){const keys=[];for(let k=target;k;k=prev.get(k))keys.unshift(k);path=[a.c,...keys.map(k=>graph.nodes.get(k).c),b.c];}if(!path)return {available:false,reason:'已知道路没有连通，请确认现场通道或使用地图 App'};path=path.filter((p,i,all)=>!i||distance(p,all[i-1])>.1);if(path.length===1)path.push(path[0]);return {available:true,path,connectors:[[pair(start),a.c],[b.c,pair(end)]],length,lengthWithApproach:length+a.gap+b.gap,approach:a.gap+b.gap};}
export function walkingRoute(graph,stops){const legs=[];for(let i=1;i<stops.length;i++)legs.push({...walkingLeg(graph,stops[i-1],stops[i]),from:stops[i-1].id,to:stops[i].id});return {legs,missing:legs.filter(l=>!l.available).length,length:legs.filter(l=>l.available).reduce((n,l)=>n+l.lengthWithApproach,0)};}
